-- Retires Tenant.dbName, a leftover from the database-per-tenant era.
--
-- Since the move to shared tables there has been no per-tenant database, so the value
-- signup wrote (`assetmon_t_<slug>`) named nothing that existed. It was carried into the
-- access token as the `db` claim and shown in the operator console as "DB", but nothing
-- ever read it to select a database.
--
-- Generated by `prisma migrate diff`, not written by hand.

-- DropIndex
DROP INDEX `Tenant_dbName_key` ON `Tenant`;

-- AlterTable
ALTER TABLE `Tenant` DROP COLUMN `dbName`;
